   202          ptr->version = gf_bs_read_u16(bs);
   203          ptr->revision = gf_bs_read_u16(bs);
   204          ptr->vendor = gf_bs_read_u32(bs);
   205          ptr->channel_count = gf_bs_read_u16(bs);
