   209          ptr->samplerate_hi = gf_bs_read_u16(bs);
   210          ptr->samplerate_lo = gf_bs_read_u16(bs);
   211
   212          if (!ptr->qtff_mode) return GF_OK;
   213          //QT only
   214          if (ptr->version==1) {
   215                  ISOM_DECREASE_SIZE(ptr, 16)
   216                  gf_bs_read_data(bs, (char *) ptr->extensions, 16);
   217          } else if (ptr->version==2) {
   218                  ISOM_DECREASE_SIZE(ptr, 36)
