  1808                  GF_LOG(GF_LOG_ERROR, GF_LOG_CONTAINER, ("[iso file] Delete invalid box type %s without registry\n", gf_4cc_to_str(a->type) ));
  1809          } else {
  1810                  a_box_registry->del_fn(a);
  1811          }
