  1842  void gf_isom_check_position(GF_Box *s, GF_Box *child, u32 *pos)
  1843  {
  1844          if (!s || !s->child_boxes || !child || !pos) return;
  1845          if (s->internal_flags & GF_ISOM_ORDER_FREEZE)
  1845          if (s->internal_flags & GF_ISOM_ORDER_FREEZE)
  1846                  return;
  1847
  1848          s32 cur_pos = gf_list_find(s->child_boxes, child);
  1849
  1850          assert (cur_pos >= 0);
  1851
  1852          if (cur_pos != (s32) *pos) {
  1853                  gf_list_del_item(s->child_boxes, child);
  1854                  gf_list_insert(s->child_boxes, child, *pos);
  1855          }
  1856          (*pos)++;
