  1873  GF_Err gf_isom_box_write(GF_Box *a, GF_BitStream *bs)
  1874  {
  1875          GF_Err e;
  1876          u64 pos = gf_bs_get_position(bs);
  1877          if (!a) return GF_BAD_PARAM;
  1878          //box has been disabled, do not write
  1879          if (!a->size) return GF_OK;
  1880
  1881          if (a->registry->disabled) {
  1882                  GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[iso file] Box %s disabled registry, skip write\n", gf_4cc_to_str(a->type)));
  1883                  return GF_OK;
  1884          }
  1885
  1886          GF_LOG(GF_LOG_DEBUG, GF_LOG_CONTAINER, ("[iso file] Box %s size %d write\n", gf_4cc_to_str(a->type), a->size));
  1887          e = gf_isom_box_write_listing(a, bs);
  1888          if (e) return e;
  1889          if (a->child_boxes) {
  1890                  e = gf_isom_box_array_write(a, a->child_boxes, bs);
  1891          }
  1892          pos = gf_bs_get_position(bs) - pos;
  1893          if (pos != a->size) {
  1894                  if (a->type != GF_ISOM_BOX_TYPE_MDAT) {
  1895                          GF_LOG(GF_LOG_WARNING, GF_LOG_CONTAINER, ("[iso file] Box %s wrote "LLU" bytes but size is "LLU"\n", gf_4cc_to_str(a->type), pos, a->size ));
  1896                  }
  1897          }
  1898          return e;
  1899  }
