    77          if (!strnicmp(strUUID, "D4807EF2CA3946958E5426CB9E46A79F", 32))
    78                  return GF_ISOM_BOX_UUID_TFRF;
    79          if (!strnicmp(strUUID, "6D1D9B0542D544E680E2141DAFF757B2", 32))
